do $$
declare tenant uuid:=gen_random_uuid();other_tenant uuid:=gen_random_uuid();admin_user uuid:=gen_random_uuid();school_user uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();school uuid:=gen_random_uuid();person uuid:=gen_random_uuid();event_uuid uuid:=gen_random_uuid();sport uuid:=gen_random_uuid();category uuid:=gen_random_uuid();staff_role uuid:=gen_random_uuid();part uuid:=gen_random_uuid();r jsonb;candidates jsonb;batch jsonb;issued jsonb;photo jsonb;second_photo jsonb;first_id uuid;
begin
 begin
  insert into auth.users(id) values(admin_user),(school_user),(outsider);
  insert into public.institutions(id,name,slug) values(tenant,'Instituição de crachás','badges-'||tenant),(other_tenant,'Outro cliente','badges-'||other_tenant);
  insert into public.institution_memberships(institution_id,user_id,role,status) values(tenant,admin_user,'admin','approved'),(other_tenant,outsider,'admin','approved');
  insert into public.schools(id,institution_id,name) values(school,tenant,'Escola autorizada');
  insert into public.people(id,institution_id,full_name,birth_date,cpf,gender) values(person,tenant,'Nome da emissão original','2003-01-01','52998224725','Feminino');
  insert into public.school_people(institution_id,school_id,person_id,role,status,user_id,position) values(tenant,school,person,'athlete','approved',null,null),(tenant,school,person,'staff','approved',null,'Técnico'),(tenant,school,person,'responsible','approved',school_user,null);
  insert into public.events(id,institution_id,name,edition,status) values(event_uuid,tenant,'Evento correto','2026','open');
  insert into public.event_modalities(id,institution_id,event_id,name,classification) values(sport,tenant,event_uuid,'Atletismo','individual');
  insert into public.event_categories(id,institution_id,event_id,modality_id,name,participation,min_athletes,max_athletes) values(category,tenant,event_uuid,sport,'Livre','individual',1,1);
  insert into public.event_staff_roles(id,institution_id,event_id,name) values(staff_role,tenant,event_uuid,'Técnico');
  perform set_config('request.jwt.claim.sub',admin_user::text,true);
  execute 'set local role authenticated';
  perform public.siep_save_participation(event_uuid,school,person,array[category],'{}',true);
  select id into part from public.event_participations where event_id=event_uuid and person_id=person;
  r:=public.siep_save_registration(event_uuid,school,category,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),jsonb_build_array(jsonb_build_object('person_id',person,'staff_role_id',staff_role)));
  if public.siep_badge_candidates(event_uuid)<>'[]'::jsonb then raise exception 'Rascunho liberou crachá';end if;
  r:=public.siep_transition_registration((r->>'id')::uuid,(r->>'revision')::integer,'submitted','Enviar');
  if public.siep_badge_candidates(event_uuid)<>'[]'::jsonb then raise exception 'Inscrição em análise liberou crachá';end if;
  r:=public.siep_transition_registration((r->>'id')::uuid,(r->>'revision')::integer,'approved','Conferido');
  candidates:=public.siep_badge_candidates(event_uuid);
  if jsonb_array_length(candidates)<>3 then raise exception 'Papéis do evento não foram listados';end if;
  select jsonb_agg(jsonb_build_object('person_id',value->>'person_id','school_id',value->>'school_id','role',value->>'role')) into batch from jsonb_array_elements(candidates);
  begin perform public.siep_issue_event_badges(event_uuid,batch);raise exception 'Emissão sem foto aceita';exception when check_violation then null;end;
  photo:=public.siep_prepare_person_photo(person,'foto.png','image/png',20);
  insert into storage.objects(bucket_id,name,owner_id,metadata) values('siep-person-photos',photo->>'path',admin_user::text,'{"size":20,"mimetype":"image/png"}');
  perform public.siep_finalize_person_photo((photo->>'id')::uuid);
  issued:=public.siep_issue_event_badges(event_uuid,batch);first_id:=(issued->0->>'id')::uuid;
  if jsonb_array_length(issued)<>3 or issued->0->'snapshot'->>'event_name'<>'Evento correto' or issued->0->'snapshot'->>'school_name'<>'Escola autorizada' or issued->0->'snapshot'->>'photo_id'<>photo->>'id' then raise exception 'Snapshot incorreto';end if;
  if issued->0->'snapshot' ? 'cpf' or issued->0->'snapshot' ? 'birth_date' then raise exception 'Dados civis desnecessários no crachá';end if;
  begin perform public.siep_issue_event_badges(event_uuid,jsonb_build_array(batch->0,jsonb_build_object('person_id',gen_random_uuid(),'school_id',school,'role','athlete')));raise exception 'Pessoa fora do evento recebeu crachá';exception when check_violation then null;end;
  if (select count(*) from public.event_badges where event_id=event_uuid)<>3 then raise exception 'Lote inválido deixou emissão parcial';end if;
  begin perform public.siep_issue_event_badges(event_uuid,jsonb_build_array(batch->0,batch->0));raise exception 'Pessoa duplicada no lote';exception when check_violation then null;end;
  execute 'reset role';
  update public.people set full_name='Nome atualizado' where id=person;
  execute 'set local role authenticated';
  second_photo:=public.siep_prepare_person_photo(person,'nova.jpg','image/jpeg',21,(photo->>'id')::uuid);
  insert into storage.objects(bucket_id,name,owner_id,metadata) values('siep-person-photos',second_photo->>'path',admin_user::text,'{"size":21,"mimetype":"image/jpeg"}');
  perform public.siep_finalize_person_photo((second_photo->>'id')::uuid);
  issued:=public.siep_issue_event_badges(event_uuid,batch);
  if (issued->0->>'version')::integer<>2 or issued->0->'snapshot'->>'photo_id'<>second_photo->>'id' then raise exception 'Nova emissão não versionada';end if;
  if not exists(select 1 from public.event_badges where id=first_id and not is_current and snapshot->>'person_name'='Nome da emissão original' and photo_id=(photo->>'id')::uuid) then raise exception 'Histórico da emissão alterado';end if;
  execute 'reset role';
  begin update public.event_badges set snapshot='{}' where id=first_id;raise exception 'Snapshot antigo sobrescrito';exception when check_violation then null;end;
  update public.people set archived=true where id=person;
  execute 'set local role authenticated';
  if not exists(select 1 from storage.objects where bucket_id='siep-person-photos' and name=photo->>'path') then raise exception 'Secretaria não conseguiu ler foto histórica';end if;
  execute 'reset role';
  perform set_config('request.jwt.claim.sub',school_user::text,true);
  execute 'set local role authenticated';
  if exists(select 1 from public.event_badges where event_id=event_uuid) then raise exception 'Escola consultou emissões exclusivas da Secretaria';end if;
  begin perform public.siep_badge_candidates(event_uuid);raise exception 'Escola executou emissão';exception when insufficient_privilege then null;end;
  execute 'reset role';
  perform set_config('request.jwt.claim.sub',outsider::text,true);
  execute 'set local role authenticated';
  begin perform public.siep_issue_event_badges(event_uuid,batch);raise exception 'Outra instituição emitiu crachás';exception when insufficient_privilege then null;end;
  execute 'reset role';
  execute 'set local role anon';
  begin perform public.siep_badge_candidates(event_uuid);raise exception 'Anon consultou crachás';exception when insufficient_privilege then null;end;
  execute 'reset role';
  raise exception 'rollback_event_badges' using errcode='ZX001';
 exception when sqlstate 'ZX001' then null;
 end;
end $$;
